// 解析查詢參數
const query = $input.first().json.query || {};

const category = query.category || '';   // 案件類型篩選（空=全部）
const status   = query.status   || '';   // 案件狀態篩選（空=全部）
const page     = parseInt(query.page) || 1;
const pageSize = 15;

return [{
  json: { category, status, page, pageSize, offset: (page - 1) * pageSize }
}];

const params = $('解析查詢參數').first().json;
const { category, status, page, pageSize, offset } = params;

const allItems = $input.all();

const getString = (prop) => {
  if (!prop) return '';
  if (prop.type === 'title')      return (prop.title     || []).map(t => t.plain_text).join('');
  if (prop.type === 'rich_text')  return (prop.rich_text || []).map(t => t.plain_text).join('');
  if (prop.type === 'select')     return prop.select?.name || '';
  if (prop.type === 'checkbox')   return prop.checkbox || false;
  if (prop.type === 'created_time')    return prop.created_time || '';
  if (prop.type === 'last_edited_time') return prop.last_edited_time || '';
  if (prop.type === 'phone_number') return prop.phone_number || '';
  return '';
};

const getImages = (prop) => {
  if (!prop || prop.type !== 'files') return [];
  return (prop.files || []).map(f => f.file?.url || f.external?.url || '').filter(Boolean);
};

let items = allItems.map(item => {
  const props = item.json.properties;
  return {
    caseId:       getString(props['案件編號']),
    caseType:     getString(props['案件類型']),
    caseArea:     getString(props['案件區域']),
    title:        getString(props['案件標題']),
    status:       getString(props['案件狀態']),
    summary:      getString(props['公開摘要']),
    reply:        getString(props['回覆內容']),
    beforeImages: getImages(props['改善前圖片']),
    afterImages:  getImages(props['改善後圖片']),
    date:         getString(props['建立時間']).slice(0, 10),
    lastUpdate:   getString(props['上次編輯時間']).slice(0, 10)
  };
});

// 篩選
if (category) items = items.filter(i => i.caseType === category);
if (status)   items = items.filter(i => i.status   === status);

// 排序：新到舊
items.sort((a, b) => b.date.localeCompare(a.date));

// 各分類計數
const categories = {};
const typeList = ['交通運輸','公共設施','衛福勞動','文教科技','環境建管','警消政風','市政議題','其他服務'];
typeList.forEach(t => { categories[t] = 0; });
allItems.forEach(item => {
  const t = item.json.properties['案件類型']?.select?.name || '';
  if (categories[t] !== undefined) categories[t]++;
});

// 分頁
const total = items.length;
const paged = items.slice(offset, offset + pageSize);

return [{
  json: {
    success: true,
    total,
    page,
    pageSize,
    totalPages: Math.ceil(total / pageSize),
    categories,
    items: paged
  }
}];
